# flake8: noqa
# ruff: noqa
import xmltodict
import re
from collections import OrderedDict
from pathlib import Path
import os
import copy
import pathlib


class AcgScfcMigrator:
    HOME_PATH = pathlib.Path.home()

    def __init__(self, golden_scfc_path, iphy_scfc_path):
        self.golden_scfc_path = golden_scfc_path
        self.iphy_scfc_path = iphy_scfc_path
        self.rrh_list = self.get_rrh_file()
        self.golden_scfc = self.open_xml_file(self.golden_scfc_path)['raml']['cmData']['managedObject']
        self.iphy_scfc = self.open_xml_file(self.iphy_scfc_path)['raml']['cmData']['managedObject']
        self.iphy_raw_scfc = self.open_xml_file(self.iphy_scfc_path)

    def get_rrh_file(self):
        iphy_xml = Path(os.path.abspath(__file__)).parents[1] / "config" / "iphy_db.xml"
        with iphy_xml.open() as f:
            return xmltodict.parse(f.read())

    def open_xml_file(self, path):
        with open(path) as fd:
            return xmltodict.parse(fd.read())

    def change_smod(self, iphy_xml, golden_xml):
        print("-- CHANGE SMOD --")
        for mo in iphy_xml:
            if 'com.nokia.srbts.eqm:SMOD' == mo['@class']:
                prod_code = ''
                for params in mo['p']:
                    if params.get('@name', '') == 'prodCodePlanned':
                        prod_code = params.get('#text')
                mo['p'] = self.find_key_with_name(golden_xml, mo['@distName'], prod_code)

    def find_key_with_name(self, golden_xml, name, old_prod_code):
        for mo in golden_xml:
            if mo['@distName'] == name:
                for params in mo['p']:
                    if params.get('@name', '') == 'prodCodePlanned':
                        new_prod_code = params.get('#text')
                print(f"Prod code {old_prod_code} changed to {new_prod_code}")
                return mo['p']

    def mo_to_delete(self, iphy_xml):
        print("-- MO TO DELETE --")
        mo_list_to_delete = []
        mo_to_check = ['CABINET', 'APEQM', 'GNSSE', 'TOP', 'TOPP', 'TOPF', 'CLOCK', 'SYNC', 'DNS', 'ETHLK', 'BBMOD',
                       'IPRT', 'IPADDRESSV4']
        for mo in iphy_xml:
            if any(obj == re.search(r':([^:]+)$', mo['@class']).group(1) for obj in mo_to_check):
                print(f"Deleted class {mo['@class']}")
                mo_list_to_delete.append(mo)
        iphy_xml[:] = [mo_c for mo_c in iphy_xml if mo_c not in mo_list_to_delete]
        return iphy_xml

    def add_mo(self, iphy_xml, golden_xml):
        print("-- ADD CLASS --")
        mo_list_to_add = ['CABINET', 'APEQM', 'GNSSE', 'CLOCK', 'SYNC', 'DNS', 'ETHLK', 'BBMOD', 'IPRT', 'IPADDRESSV4']
        for mo_golden in golden_xml:
            if any(obj == re.search(r':([^:]+)$', mo_golden['@class']).group(1) for obj in mo_list_to_add):
                print(f"Add class {mo_golden['@class']}")
                iphy_xml.append(mo_golden)

    def set_necessary_param(self, iphy_xml, old_iphy):
        print("-- SET NECESSARY PARAM --")
        for mo in iphy_xml:
            if mo.get('@class', '') == 'com.nokia.srbts.mnl:SECADM':
                for param in mo['p']:
                    if param.get('@name', '') == 'ethernetPortSecurityEnabled':
                        print("Set ethernetPortSecurityEnabled")
                        param['#text'] = "false"
                    if param.get('@name', '') == 'actServiceAccountSsh':
                        print("Set actServiceAccountSsh")
                        param['#text'] = "true"
            if mo.get('@class', '') == 'com.nokia.srbts.mnl:FEATCADM':
                for param in mo['p']:
                    if param.get('@name', '') == 'systemAcctPermEnable':
                        print('Set systemAcctPermEnable')
                        param['#text'] = "false"
            if mo.get('@class', '') == 'NOKLTE:LNBTS':
                params_to_update = [{'@name': 'bbPoolMinResource', '#text': '5'},
                                    {'@name': 'bbPoolEvalPeriod', '#text': '50'}]
                for param in params_to_update:
                    param_name = param['@name']
                    param_text = param['#text']
                    found = False
                    for params_in_mo in mo['p']:
                        if params_in_mo.get('@name') == param_name:
                            found = True
                            params_in_mo['#text'] = param_text
                    if not found:
                        mo['p'].append(OrderedDict([('@name', param_name), ('#text', param_text)]))
                        print(f"Add {param_name} = {param_text}")

            if mo.get('@class', '') == 'NOKLTE:LNBTS_FDD':
                params_to_update = [{'@name': 'maxBtsTimeError', '#text': '1000'}]
                for param in params_to_update:
                    param_name = param['@name']
                    param_text = param['#text']
                    found = False
                    for params_in_mo in mo['p']:
                        if params_in_mo.get('@name') == param_name:
                            print("Update maxBtsTimeError to 1000")
                            found = True
                            params_in_mo['#text'] = param_text
                    if not found:
                        mo['p'].append(OrderedDict([('@name', param_name), ('#text', param_text)]))
                        print("Add maxBtsTimeError = 1000")

            if mo.get('@class', '') == 'NOKLTE:APUCCH_TDD':
                for param in mo['p']:
                    if param.get('@name', '') == 'actLbPucchReg':
                        print("Set actLbPucchReg to true")
                        param['#text'] = "true"

            if mo.get('@class', '') == 'com.nokia.srbts.tnl:BRGPRT':
                for param in mo['p']:
                    if param.get('@name', '') == 'l2BurstSize':
                        print("Set l2BurstSize to 1048576")
                        param['#text'] = "1048576"

            if mo.get('@class', '') == 'com.nokia.srbts.eqm:BBMOD':
                # if mo.get('@distName', '') in bbpoolsizelte_dict.keys():
                #     param = [bbpoolsizelte_dict[dist_name] for dist_name in bbpoolsizelte_dict.keys() if
                #              dist_name == mo.get('@distName', '')]
                #     mo['p'].append(OrderedDict([('@name', 'bbPoolSizeLte'), ('#text', param[0])]))
                #     print(f"Add bbPoolSizeLte = {param[0]}")
                params_to_update = [{'@name': 'bbPoolSizeLte', '#text': 'extended'},
                                    {'@name': 'bbCardUsage', '#text': '2'}]
                for param in params_to_update:
                    param_name = param['@name']
                    param_text = param['#text']
                    found = False
                    for params_in_mo in mo['p']:
                        if params_in_mo.get('@name') == param_name:
                            print("Update bbPoolSizeLte to extended")
                            found = True
                            params_in_mo['#text'] = param_text
                    if not found:
                        mo['p'].append(OrderedDict([('@name', param_name), ('#text', param_text)]))
                        print("Add bbPoolSizeLte = extended")

    def get_bbool_param_if_exist(self, iphy, old_iphy):
        bbpoolsizelte_dict = {}
        old_bbpoolsizelte_dict = {}
        for old_mo in old_iphy:
            if old_mo.get('@class', '') == 'com.nokia.srbts.eqm:BBMOD':
                for param in old_mo['p']:
                    if param.get('@name', '') == 'bbPoolSizeLte':
                        bbpoolsizelte_dict[old_mo.get('@distName', '')] = param.get('#text', '')
        for mo in iphy:
            if mo.get('@class', '') == 'com.nokia.srbts.eqm:BBMOD':
                for param in mo['p']:
                    if param.get('@name', '') == 'bbPoolSizeLte':
                        old_bbpoolsizelte_dict[mo.get('@distName', '')] = param.get('#text', '')

        if bbpoolsizelte_dict != old_bbpoolsizelte_dict:
            return bbpoolsizelte_dict
        else:
            return {}

    def set_radio_protocol_type(self, iphy_xml):
        for mo in iphy_xml:
            if mo.get('@class', '') == 'com.nokia.srbts.eqm:CABLINK':
                sec_endp = [param for param in mo['p'] if "/RMOD-" in param['#text']]
                if sec_endp and self.is_allowed_radio_protocol_type(iphy_xml, mo):
                    print("-- SET PROTOCOL TYPE --")
                    add_radio_protocol = True
                    for param in mo['p']:
                        if param.get('@name') == 'radioProtocolType':
                            add_radio_protocol = False

                    if add_radio_protocol:
                        protocol_type = self.get_protocol_type_depend_on_rmod(iphy_xml, mo)
                        mo['p'].append(OrderedDict([('@name', 'radioProtocolType'), ('#text', protocol_type)]))
                        print(f'Add radioProtocolType {protocol_type} to {mo["@distName"]}')

    def get_protocol_type_depend_on_rmod(self, iphy_xml, mo):
        radio_dist_name = ''
        for params in mo['p']:
            if params.get('@name', '') == 'secondEndpointDN':
                radio_dist_name = params.get('#text')
        for mo in iphy_xml:
            if mo['@distName'] == radio_dist_name:
                for params_radio in mo['p']:
                    if params_radio.get('@name', '') == 'prodCodePlanned':
                        radio_prod_code = params_radio.get('#text')
                        for antenna in self.rrh_list['RF_Unit_Database']['RRH_List']['RRH']:
                            if antenna['productcode'] == radio_prod_code:
                                if antenna['obsai'] == "true":
                                    # print("OBSAI")
                                    return "OBSAI"
                                elif antenna['ecpri'] == "true":
                                    # print("eCPRI")
                                    return 'eCPRI'
                                else:
                                    # print("CPRI")
                                    return 'CPRI'

    def is_allowed_radio_protocol_type(self, iphy_xml, mo):
        bbmod_dist_name = ''
        bbmod_prod_code = ''
        for params in mo['p']:
            if params.get('@name', '') == 'firstEndpointDN':
                bbmod_dist_name = params.get('#text')
        for mobj in iphy_xml:
            if mobj['@distName'] == bbmod_dist_name:
                for params_bbmod in mobj['p']:
                    if params_bbmod.get('@name', '') == 'prodCodePlanned':
                        bbmod_prod_code = re.search(r'(\d+[A-Z]+)(?:\.\d+)?', params_bbmod.get('#text')).group(1)
        # ABIC,ABIL,ABIO,ABIN,ABIP,ABIQ
        if bbmod_prod_code in ['474723A', '474020A', '475266A', '474824A', '475792A', '476397A']:
            return True
        else:
            print(f"radioProtocolType is not allowed for this BBMOD {bbmod_prod_code}")

    def check_if_smod_ext_exist(self, iphy_xml):
        for mo in iphy_xml:
            if mo.get('@class', '') == 'com.nokia.srbts.eqm:CABLINK':
                for param in mo['p']:
                    if param.get('@name', '') == 'firstEndpointDN' and 'SMOD_EXT' in param['#text']:
                        return True

    def set_link_speed(self, iphy_xml):
        smod_ext = self.check_if_smod_ext_exist(iphy_xml)
        if not smod_ext:
            print("-- SET LINK SPEED --")
            for mo in iphy_xml:
                if mo.get('@class', '') == 'com.nokia.srbts.eqm:CABLINK':
                    link_speed_exist = False
                    correct_cablink = False
                    for param in mo['p']:
                        if param.get('@name', '') == 'secondEndpointDN' and 'RMOD' in param['#text']:
                            rmod_dist_name = param['#text']
                            link_speed_exist = self.check_if_link_speed_exist(mo)
                            correct_cablink = True

                    if not link_speed_exist and correct_cablink:
                        link_speed = self.get_link_speed_depend_on_rmod(iphy_xml, mo)
                        if link_speed:
                            mo['p'].append(OrderedDict([('@name', 'linkSpeed'), ('#text', link_speed)]))
                            print(f"Add linkSpeed {link_speed} to {mo['@distName']} for {rmod_dist_name}")

    def get_link_speed_depend_on_rmod(self, iphy_xml, mo):
        radio_dist_name = ''
        for params in mo['p']:
            if params.get('@name', '') == 'secondEndpointDN':
                radio_dist_name = params.get('#text')
        for mo in iphy_xml:
            if mo['@distName'] == radio_dist_name:
                for params_radio in mo['p']:
                    if params_radio.get('@name', '') == 'prodCodePlanned':
                        radio_prod_code = re.search(r'(\d+[A-Z]+)(?:\.\d+)?', params_radio.get('#text')).group(1)
                        for antenna in self.rrh_list['RF_Unit_Database']['RRH_List']['RRH']:
                            if antenna['productcode'] == radio_prod_code:
                                print(f"Detected radio {antenna['productname']} for {radio_dist_name}")
                                if antenna['obsai'] == "true":
                                    print("Set linkSpeed to Obsai6Gbps")
                                    return "Obsai6Gbps"
                                elif antenna['ecpri'] == "true":
                                    print("Set linkSpeed to eCpri25")
                                    return 'eCpri25'
                                else:
                                    print("Set linkSpeed to Cpri7")
                                    return 'Cpri7'

    def check_if_link_speed_exist(self, mo):
        for param in mo['p']:
            if param.get("@name") == 'linkSpeed':
                print("linkSpeed exist")
                return True

    def update_cablinks(self, scfc_with_new_bbmods, iphy_scfc):
        print("-- UPDATE CABLINKS --")
        prod_code = ''
        for mo in scfc_with_new_bbmods:
            if 'com.nokia.srbts.eqm:BBMOD' == mo['@class']:
                dist_name = mo['@distName']
                for params in mo['p']:
                    if params.get('@name', '') == 'prodCodePlanned':
                        prod_code = re.search(r'(\d+[A-Z]+)(?:\.\d+)?', params.get('#text')).group(1)

                for old_mo in iphy_scfc:
                    if dist_name == old_mo['@distName']:
                        for params_old in old_mo['p']:
                            if params_old.get('@name', '') == 'prodCodePlanned':
                                old_prod_code = re.search(r'(\d+[A-Z]+)(?:\.\d+)?', params_old.get('#text')).group(1)
                                if prod_code != old_prod_code:
                                    print(f"Different prod code found for {dist_name}")
                                    # self.find_cablink_with_indicated_bbmod(scfc_with_new_bbmods, dist_name,
                                    #                                        old_prod_code)
                                else:
                                    print(f"Product code are the same for {dist_name}")

    def find_cablink_with_indicated_bbmod(self, scfc_with_new_bbmods, dist_name, old_prod_code):
        for mo in scfc_with_new_bbmods:
            if mo.get('@class', '') == 'com.nokia.srbts.eqm:CABLINK':
                for param in mo['p']:
                    if param.get('@name', '') == 'firstEndpointDN':
                        if param.get('#text') == dist_name:
                            new_dist_name = self.find_dist_name_with_matched_bbmod(old_prod_code, scfc_with_new_bbmods)
                            param['#text'] = new_dist_name
                            print(f"For {mo['@distName']} firstendpointDN changed from {dist_name} to {new_dist_name}")

    def find_dist_name_with_matched_bbmod(self, old_prod_code, scfc_with_new_bbmod):
        for mo in scfc_with_new_bbmod:
            if 'com.nokia.srbts.eqm:BBMOD' == mo['@class']:
                for param in mo['p']:
                    if param.get('@name', '') == 'prodCodePlanned':
                        if old_prod_code == param.get('#text'):
                            return mo['@distName']
                    else:
                        # TODO zrobic obsluge jak nie ma takiego bbmoda
                        # TODO wycieta funkcja wy?ej dopasowuj?ca cablink
                        print("")

    def add_bb_pooling(self, iphy):
        iphy_copy = copy.copy(iphy)
        mandatory, bbpoolalloc_distname_list, apucch_fdd_distname_list = self.check_if_bbpool_is_mandatory(iphy)
        if mandatory:
            for mo in iphy_copy:
                if 'NOKLTE:LNCEL' == mo['@class']:
                    lncel_dist_name = mo['@distName']
                    bbpoolalloc_distname = lncel_dist_name + "/BBPOOLALLOC-0"
                    if bbpoolalloc_distname not in bbpoolalloc_distname_list:
                        self.add_bbpoolalloc_mo(iphy, mo, bbpoolalloc_distname)

                if 'NOKLTE:LNCEL_FDD' == mo['@class']:
                    lncel_fdd_dist_name = mo['@distName']
                    appucch_fdd_distname = lncel_fdd_dist_name + "/APUCCH_FDD-0"
                    if appucch_fdd_distname not in apucch_fdd_distname_list:
                        self.add_apucch_fdd_mo(iphy, mo, appucch_fdd_distname)

            for mo in iphy:
                if mo.get('@class', '') == 'NOKLTE:LNBTS':
                    for param in mo['p']:
                        if param.get('@name', '') == 'actBbPooling':
                            print("Set actBbPooling to true")
                            param['#text'] = "true"

                if mo.get('@class', '') == 'NOKLTE:APUCCH_FDD':
                    params_to_update = [{'@name': 'actLbPucchReg', '#text': 'true'},
                                        {'@name': 'pucchArRateEvalWinLength', '#text': '0'},
                                        {'@name': 'aPucchSrPeriodUpperLimit', '#text': '40'}]
                    for param in params_to_update:
                        param_name = param['@name']
                        param_text = param['#text']
                        found = False
                        for params_in_mo in mo['p']:
                            if params_in_mo.get('@name') == param_name:
                                found = True
                                params_in_mo['#text'] = param_text
                        if not found:
                            mo['p'].append(OrderedDict([('@name', param_name), ('#text', param_text)]))
                            print(f"Add {param_name} = {param_text}")

                if mo.get('@class', '') == 'NOKLTE:LNCEL_FDD':
                    for param in mo['p']:
                        if param.get('@name', '') == 'actAutoPucchAlloc':
                            print("Set actAutoPucchAlloc to true")
                            param['#text'] = "true"

    def add_apucch_fdd_mo(self, iphy, mo, appucch_fdd_distname):
        iphy.append(OrderedDict([('@class', 'NOKLTE:APUCCH_FDD'),
                                 ('@distName', appucch_fdd_distname),
                                 ('@operation', 'create'), ('@version', mo['@version']),
                                 ('p', [OrderedDict([('@name', 'aPucchAddAUeRrHo'), ('#text', '10')]),
                                        OrderedDict([('@name', 'aPucchAddAUeTcHo'), ('#text', '15')]),
                                        OrderedDict([('@name', 'aPucchMinNumEmergencySessions'), ('#text', '10')]),
                                        OrderedDict([('@name', 'aPucchMinNumRrc'), ('#text', '10')]),
                                        OrderedDict([('@name', 'aPucchMinNumRrcNoDrb'), ('#text', '5')]),
                                        OrderedDict([('@name', 'aPucchSrPeriodUpperLimit'), ('#text', '40')]),
                                        OrderedDict([('@name', 'actLbPucchReg'), ('#text', 'true')]),
                                        OrderedDict([('@name', 'pucchArRateEvalWinLength'), ('#text', '0')]),
                                        OrderedDict([('@name', 'selectPrachRegion'), ('#text', 'None')])])]))
        print("Add mo APUCCH_FDD")

    def add_bbpoolalloc_mo(self, iphy, mo, bbpoolalloc_distname):
        iphy.append(OrderedDict([('@class', 'NOKLTE:BBPOOLALLOC'), ('@distName', bbpoolalloc_distname),
                                 ('@operation', 'create'), ('@version', mo['@version']),
                                 ('p', OrderedDict([('@name', 'bbPoolAllocMode'), ('#text', 'automatic')]))]))
        print("Add mo BBPOOLALLOC")

    def check_if_bbpool_is_mandatory(self, iphy_xml):
        bbmod_list = []
        bbpoolalloc_distname_list = []
        apucch_fdd_distname_list = []
        for mo in iphy_xml:
            if 'com.nokia.srbts.eqm:BBMOD' == mo['@class']:
                for param in mo['p']:
                    if param.get('@name', '') == 'prodCodePlanned':
                        bbmod_list.append(re.search(r'(\d+[A-Z]+)(?:\.\d+)?', param.get('#text')).group(1))

            if 'NOKLTE:BBPOOLALLOC' == mo['@class']:
                bbpoolalloc_distname_list.append(mo['@distName'])
            if 'NOKLTE:APUCCH_FDD' == mo['@class']:
                apucch_fdd_distname_list.append(mo['@distName'])
        if any(bbmod in ['474723A', '474020A', '475266A', '474824A', '475792A', '476397A'] for bbmod in bbmod_list):
            return True, bbpoolalloc_distname_list, apucch_fdd_distname_list
        else:
            return False, bbpoolalloc_distname_list, apucch_fdd_distname_list

    def save_file(self, iphy_raw_scfc, iphy_scfc_path):
        old_filename = re.search(r"/([^/]+)\.xml$", iphy_scfc_path).group(1)
        filename = f"{old_filename}_CUS.xml"
        output_dir = Path(self.HOME_PATH / 'output_config_migrator')
        output_dir.mkdir(parents=True, exist_ok=True)
        filepath = Path(output_dir) / filename
        with filepath.open(mode='w', encoding='utf-8') as fd:
            fd.write(xmltodict.unparse(iphy_raw_scfc))

    def migrate_scfc(self):
        old_iphy = copy.copy(self.iphy_scfc)
        self.change_smod(self.iphy_scfc, self.golden_scfc)
        iphy = self.mo_to_delete(self.iphy_scfc)
        self.add_mo(iphy, self.golden_scfc)
        self.update_cablinks(iphy, old_iphy)
        self.set_necessary_param(iphy, old_iphy)
        self.set_radio_protocol_type(iphy)
        self.set_link_speed(iphy)
        self.add_bb_pooling(iphy)
        self.iphy_raw_scfc['raml']['cmData']['managedObject'] = iphy
        self.save_file(self.iphy_raw_scfc, self.iphy_scfc_path)


if __name__ == '__main__':
    migrator = AcgScfcMigrator(golden_scfc_path, iphy_scfc_path)
    migrator.migrate_scfc()
